function frontierReadingLink(w){const t=w.s[5],profile=t==='渔家傲·秋思'?'songxia':['使至塞上','白雪歌送武判官归京'].includes(t)?'tang':null;return profile?`<a class="reader-studio frontier-link" href="index.html?frontier=${profile}&reading=${encodeURIComponent(w.meta.id)}">看边疆与时代背景 ↗</a>`:'';}
let libraryStage='all',libraryLimit=24;
function scopeBadge(s){const m=s[11];return `<span class="scope-badge ${m.scope==='课标背诵'?'core':''}">${m.stage==='拓展'?'衔接':m.stage} · ${m.scope}</span>`;}
function escapeHtml(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function scopeSource(m){return m.scope==='课标背诵'?curriculumSources[m.stage==='初中'?'junior':'high']:m.scope==='小学衔接'?curriculumSources.junior:curriculumSources.textbook;}
function readWork(id){
 const w=findReadingWork(id);if(!w)return;const {s,meta:m}=w,source=scopeSource(m),units=readingUnits(w),selection=m.selection||units[0]?.selection||'全文';
 showModal(`<p class="eyebrow">${escapeHtml(workAuthor(w))} · ${escapeHtml(m.kind)} · ${selection==='全文'?'全文赏读':'原文与选段'}</p><h2>${escapeHtml(s[5])}</h2>${scopeBadge(s)}<p class="reader-meta">${escapeHtml(s[0])}${w.featured?' · '+escapeHtml(s[1])+' · '+m.role:' · 篇目总库'}${m.course?' · '+escapeHtml(m.course):''}</p>${selection!=='全文'?`<p class="selection-note"><strong>收录范围：</strong>${escapeHtml(selection)}</p>`:''}<div class="reader-toolbar"><button id="hideText">遮住原文，自主背诵</button>${w.featured?'<button id="locateWork">在地图中查看 →</button>':''}<a class="reader-studio" href="studio.html?work=${encodeURIComponent(id)}">带着这一篇去创作 ↗</a></div>${frontierReadingLink(w)}<div id="readerText" class="reader-text ${readingCategory(w)==='文言文'?'prose':''}">${escapeHtml(s[6])}</div>${workImageGallery(w)}<div class="reader-notes"><h3>${w.featured?'读懂这一篇':'阅读起点'}</h3><p>${escapeHtml(s[8])}</p><h3>赏读与复习</h3><p>${escapeHtml(m.focus)}</p><h3>想一想</h3><p>${escapeHtml(s[10])}</p>${lessonCTA(id)}<h3>篇目依据与文本说明</h3><p><a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.label} ↗</a>${source.pages?' · '+source.pages:''}</p><p>${m.scope==='版本补充'?'旧版教材整理与版本衔接篇目，不计入2025课标附录覆盖率；不同学制、册次与地区使用范围须核对教材。':m.scope==='教材补充'?'教材补充不等于课标附录；请核对实际所用课本。':m.scope==='小学衔接'?'小学衔接阅读，不计入初高中课标附录。':'按2025日常修订版课标附录整理。目录不是全国统一考试题库；篇、段、章按附录条目统计。'}</p><p><a href="${m.textSource}" target="_blank" rel="noopener noreferrer">原文参考来源 ↗</a>${w.featured?'':` · <a href="assets/catalog/attribution.json" target="_blank">文本整理与署名 ↗</a>`}</p><p>正文采用通行简体整理；有异文或教材节选差异时，以实际教材为准。${escapeHtml(m.dateNote||'地理位置与创作系年见对应站点。')}</p></div>`);
 bindLessonButtons();bindWorkImages();if($('locateWork'))$('locateWork').onclick=()=>openWork(id);$('hideText').onclick=()=>{const hide=$('readerText').classList.toggle('text-hidden');$('readerText').setAttribute('aria-hidden',String(hide));$('hideText').textContent=hide?'显示原文，核对背诵':'遮住原文，自主背诵';};
}
function filteredWorks(){
 const author=$('authorFilter').value,scope=$('scopeFilter').value,q=$('poemSearch').value.trim(),kind=$('kindFilter')?.value||'all',course=$('courseFilter')?.value||'all';
 return getReadingWorks().filter(w=>{const {s,a,meta:m}=w;return (libraryStage==='all'||m.stage===libraryStage)&&(author==='all'||['0','1','2'].includes(author)&&a===+author||author.startsWith('name:')&&workAuthor(w)===author.slice(5))&&(scope==='all'||scope==='core'&&m.scope==='课标背诵'||scope==='extra'&&['教材补充','版本补充'].includes(m.scope)||scope==='bridge'&&m.scope==='小学衔接')&&(kind==='all'||readingCategory(w)===kind)&&(course==='all'||m.course===course||readingUnits(w).some(u=>u.course===course))&&(!q||[s[5],s[6],s[1],workAuthor(w),m.focus,m.selection||''].some(t=>t.includes(q)));});
}
function renderFeaturedPoets(){if(!$('featuredPoets'))return;$('featuredPoets').innerHTML=people.map((p,a)=>`<article class="featured-poet featured-poet-${a}"><span class="featured-seal">重点<br>专题</span><div class="featured-name"><span class="portrait">${p.name[0]}</span><div><h3>${p.name}</h3><p>${p.title.split('·')[0].trim()} · ${p.stops.length}篇</p></div></div><p>${p.desc}</p><div><button data-featured-author="${a}">读${p.name}的诗文 →</button><a href="index.html?work=${p.stops[0][11].id}">循足迹探索 ↗</a></div></article>`).join('');document.querySelectorAll('[data-featured-author]').forEach(b=>b.onclick=()=>{$('authorFilter').value=b.dataset.featuredAuthor;for(const id of ['scopeFilter','kindFilter','courseFilter'])if($(id))$(id).value='all';$('poemSearch').value='';libraryStage='all';libraryLimit=24;renderLibrary();$('library').scrollIntoView({behavior:'smooth',block:'start'});});}
function renderLibrary(){
 const stages=[['all','全部篇目'],['初中','初中'],['高中','高中'],['拓展','衔接与拓展']];$('stageFilters').innerHTML=stages.map(([v,t])=>`<button data-stage="${v}" aria-pressed="${libraryStage===v}">${t}</button>`).join('');document.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>{libraryStage=el.dataset.stage;libraryLimit=24;renderLibrary();});
 const works=filteredWorks(),visible=works.slice(0,libraryLimit);$('libraryCount').textContent=`找到 ${works.length} 篇 · 已显示 ${visible.length} 篇 · 三位重点诗人优先`;
 $('poemGrid').innerHTML=works.length?visible.map(w=>{const {s,meta:m}=w;return `<article class="poem-card ${w.featured?'featured-work':''}">${workImageCard(w)}${scopeBadge(s)}${w.featured?'<span class="featured-work-label">重点诗人</span>':''}<button class="card-title" data-read="${m.id}"><h3>${escapeHtml(s[5])}</h3></button><div class="card-meta">${escapeHtml(workAuthor(w))} · ${escapeHtml(m.kind)} · ${escapeHtml(s[0])}</div><p class="card-excerpt">${escapeHtml(s[6].split('\n').filter(Boolean).slice(0,2).join('\n')).replace(/\n/g,'<br>')}</p><p class="card-place">${w.featured?'⌖ '+s[1]+' <span>'+m.role+'</span>':escapeHtml(m.course)+' · '+escapeHtml(m.selection==='全文'?'全文':m.selection.includes('教材')?'版本整理':'指定选段')}</p><div class="card-actions"><button data-read="${m.id}">原文赏读 ↗</button>${w.featured?`<button data-locate="${m.id}">${m.role==='地点待考'?'查看作品 →':'地图中查看 →'}</button>`:`<a href="studio.html?work=${m.id}">带入创作坊 →</a>${frontierReadingLink(w)}`}</div></article>`;}).join(''):`<div class="empty-state"><h3>暂时没有匹配的篇目</h3><p>试试缩短关键词，或点击“重置筛选”。</p></div>`;
 document.querySelectorAll('[data-read]').forEach(el=>el.onclick=()=>readWork(el.dataset.read));document.querySelectorAll('[data-locate]').forEach(el=>el.onclick=()=>openWork(el.dataset.locate));bindWorkImages();if($('loadMoreWorks')){$('loadMoreWorks').hidden=works.length<=visible.length;$('loadMoreWorks').textContent=`再看 ${Math.min(24,works.length-visible.length)} 篇（剩余 ${works.length-visible.length} 篇）`;}
}
function coverageHtml(stage){
 if(typeof catalogUnits==='undefined')return '<p>完整覆盖清单请到篇目书架查看。</p>';
 return ['初中','高中'].filter(s=>!stage||s===stage).map(s=>`<section class="coverage-author"><h3>${s} <small>${s==='初中'?60:72}条课标目录</small></h3>${catalogUnits.filter(u=>u.stage===s).map(u=>`<button data-coverage-work="${u.workId}"><span>✓ ${String(u.order).padStart(2,'0')} ${escapeHtml(u.title)}</span><small>${escapeHtml(u.author)} · ${escapeHtml(u.course)} · 已收录</small></button>`).join('')}</section>`).join('');
}
function showCoverage(stage){showModal(`<p class="eyebrow">对照目录 · 2026年10月22日核对</p><h2>${stage||'初高中'}课标覆盖清单</h2><p>初中60条，高中72条，均已收录原文或指定选段。组合篇目按课标一条计：例如初中《孟子》三则、高中古代文论六组选段。三位重点诗人以外的篇目进入阅读库，不增加地图足迹。</p>${coverageHtml(stage)}<p><button id="openScopeFromList">查看核对依据和考试范围说明 ↗</button></p>`);document.querySelectorAll('[data-coverage-work]').forEach(el=>el.onclick=()=>readWork(el.dataset.coverageWork));$('openScopeFromList').onclick=showScope;}
function showScope(){showModal(`<p class="eyebrow">范围与依据 · 2026年10月22日核对</p><h2>按课标收齐，按教材使用</h2><p>篇目总库以2025日常修订版初高中语文课标的古诗文背诵推荐目录为主，并保留教材学习、旧版衔接与小学衔接作品。李白、杜甫、苏轼仍是地图和书架的重点人物。</p><h3>初中：60条目录</h3><p>《义务教育语文课程标准（2022年版2025年修订）》附录1，7—9年级推荐60篇（段）。<a href="${curriculumSources.junior.pdf}#page=64" target="_blank" rel="noopener noreferrer">课标PDF第64—66页 ↗</a>。其中《孟子》三则含鱼我所欲也、得道多助、生于忧患；伯牙篇目依据《吕氏春秋》，与旧汇编的《列子》选段分开。</p><h3>高中：72条目录</h3><p>《普通高中语文课程标准（2017年版2025年修订）》附录1：文言文32条（必修10、选择性必修10、选修12），诗词曲40首。<a href="${curriculumSources.high.pdf}#page=60" target="_blank" rel="noopener noreferrer">课标PDF第60—64页 ↗</a>。古代文论六组选段合计一条；《归去来兮辞》《琵琶行》均补齐序文。高中《逍遥游》收录的是“五石之瓠”段，不能套用初中“北冥有鱼”选段。</p><h3>教材与版本补充</h3><p>原有三位作者的全部37篇保留。另补入《鸿门宴》《庖丁解牛》《苏武传》《孔雀东南飞》等教材选文，标“教材补充”；旧版衔接作品标“版本补充”，不混入课标覆盖计数；不声称已逐省、逐教材版本核定考试范围。可按作者、学段、文体和高中课程类别筛选。</p><h3>考试与原文边界</h3><p>背诵目录不是统一考试题库，诗歌鉴赏、文言文阅读仍可能使用课外材料。实际备考范围以所在省市、考试年份、教材和学校通知为准。正文采用通行简体整理，异文、通假字、注本和节选以教材为准。</p><p>古典原作为公版文本；机器可读整理参考汤圆与 Clover Yan 的公开数据，整理数据依 CC BY-SA 4.0 署名与共享。<a href="assets/catalog/attribution.json" target="_blank">来源、校正与许可 ↗</a>。</p>`);}
function initLibrary(){
 const authors=[...new Set(getReadingWorks().filter(w=>!w.featured).map(workAuthor))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
 $('authorFilter').innerHTML='<option value="all">全部作者</option><optgroup label="三位重点诗人">'+people.map((p,a)=>`<option value="${a}">${p.name} · 重点专题</option>`).join('')+'</optgroup><optgroup label="其他作者与典籍">'+authors.map(a=>`<option value="name:${escapeHtml(a)}">${escapeHtml(a)}</option>`).join('')+'</optgroup>';
 const aq=new URLSearchParams(location.search).get('author');if(['0','1','2'].includes(aq))$('authorFilter').value=aq;
 renderFeaturedPoets();renderLibrary();$('scopeInfo').onclick=showScope;$('coverageList').onclick=()=>showCoverage();$('juniorCoverage').onclick=()=>showCoverage('初中');$('highCoverage').onclick=()=>showCoverage('高中');for(const id of ['authorFilter','scopeFilter','kindFilter','courseFilter'])if($(id))$(id).onchange=()=>{libraryLimit=24;renderLibrary();};$('poemSearch').oninput=()=>{libraryLimit=24;renderLibrary();};$('clearFilters').onclick=()=>{libraryStage='all';libraryLimit=24;for(const id of ['authorFilter','scopeFilter','kindFilter','courseFilter'])if($(id))$(id).value='all';$('poemSearch').value='';renderLibrary();};if($('loadMoreWorks'))$('loadMoreWorks').onclick=()=>{libraryLimit+=24;renderLibrary();};if($('catalogTotal'))$('catalogTotal').textContent=getReadingWorks().length+'篇／组原文 · 含课标条目与版本补充';
 const id=new URLSearchParams(location.search).get('work');if(id&&findReadingWork(id))readWork(id);
}
